private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null) {
        throw new IllegalArgumentException("Header part cannot be null");
    }
    if (end < 0 || end >= headerPart.length()) {
        throw new IllegalArgumentException("End index is out of bounds");
    }

    for (int i = end - 1; i >= 0; i--) {
        char currentChar = headerPart.charAt(i);
        char previousChar = (i > 0) ? headerPart.charAt(i - 1) : '\0';

        if (currentChar == '\n' && previousChar == '\r') {
            return i - 1;
        }
    }

    throw new IllegalStateException("End of line sequence not found");
}

