@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Validate the input parameters
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    // Get the vertex set from the resultMap
    Set<String> vertexSet = resultMap.keySet();
    if (vertexSet.size() % 2 != 0) {
        throw new IllegalArgumentException("The number of vertices must be even for a bipartite graph");
    }

    // Divide the vertex set into two partitions
    List<Set<V>> partitions = new ArrayList<>();
    for (int i = 0; i < 2; i++) {
        partitions.add(new HashSet<>());
    }
    int partitionIndex = 0;
    for (String vertexKey : vertexSet) {
        partitions.get(partitionIndex).add(resultMap.get(vertexKey));
        partitionIndex = (partitionIndex + 1) % 2;
    }

    // Add edges between the two partitions
    Set<V> partition1 = partitions.get(0);
    Set<V> partition2 = partitions.get(1);
    for (V v1 : partition1) {
        for (V v2 : partition2) {
            target.addEdge(v1, v2);
        }
    }
}

