public long readLong(final int offset) {
    // Step 1: Validate the input offset
    if (offset < 0) {
        throw new IllegalArgumentException("Offset cannot be negative");
    }

    // Step 2: Check if the offset is within the bounds of the data to be read
    if (offset + 7 >= data.length) {
        throw new ArrayIndexOutOfBoundsException("Offset is out of bounds for long value");
    }

    // Step 3: Read the 8 bytes at the specified offset
    byte b0 = data[offset];
    byte b1 = data[offset + 1];
    byte b2 = data[offset + 2];
    byte b3 = data[offset + 3];
    byte b4 = data[offset + 4];
    byte b5 = data[offset + 5];
    byte b6 = data[offset + 6];
    byte b7 = data[offset + 7];

    // Step 4: Combine the 8 bytes into a single long value
    return ((b0 & 0xFFL) << 56) |
           ((b1 & 0xFFL) << 48) |
           ((b2 & 0xFFL) << 40) |
           ((b3 & 0xFFL) << 32) |
           ((b4 & 0xFFL) << 24) |
           ((b5 & 0xFFL) << 16) |
           ((b6 & 0xFFL) << 8)  |
           (b7 & 0xFFL);
}

