static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        // Extract year, month, and day from the time bucket
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        // Determine the new day based on dayStep
        int newDay;
        if (dayStep >= day) {
            newDay = day;
        } else {
            newDay = day - day % dayStep;
        }

        // Create the new time bucket
        long newTimeBucket = (long) year * 10000 + month * 100 + newDay;

        return newTimeBucket;
    } catch (Exception e) {
        // Handle potential invalid inputs and runtime issues
        System.err.println("Invalid input or runtime issue: " + e.getMessage());
        return -1; // Return -1 to indicate an error
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || index >= str.length()) {
        throw new IndexOutOfBoundsException("Index " + index + " is out of bounds for length " + str.length());
    }
    if (len < 0 || (index + len) > str.length()) {
        throw new IndexOutOfBoundsException("Length " + len + " is invalid starting at index " + index + " for length " + str.length());
    }

    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1; // 1 byte for ASCII characters
        } else if (c <= 0x7FF) {
            size += 2; // 2 bytes for characters in the range 0x80 to 0x7FF
        } else if (c <= 0xFFFF) {
            size += 3; // 3 bytes for characters in the range 0x800 to 0xFFFF
        } else {
            size += 4; // 4 bytes for characters in the range 0x10000 to 0x10FFFF
        }
    }
    return size;
}

