public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    String path = u.getPath();
    if (path == null) {
        return pathSegments;
    }

    if (path.startsWith("/")) {
        path = path.substring(1);
    }

    for (String segment : path.split("/")) {
        if (!segment.isEmpty()) {
            if (decode) {
                try {
                    segment = URLDecoder.decode(segment, StandardCharsets.UTF_8.toString());
                } catch (UnsupportedEncodingException e) {
                    // Handle the exception, e.g., by logging or rethrowing
                    e.printStackTrace();
                }
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }
    }

    return pathSegments;
}

