public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }

    int prime = desiredCapacity;
    boolean found = false;

    while (!found) {
        if (isPrime(prime)) {
            found = true;
        } else {
            prime++;
        }

        if (desiredCapacity >= 1000) {
            if (prime >= desiredCapacity + (desiredCapacity * 0.11)) {
                break;
            }
        } else {
            if (prime >= desiredCapacity + 2) {
                break;
            }
        }
    }

    return prime;
}

private static boolean isPrime(int num) {
    if (num <= 1) {
        return false;
    }
    if (num <= 3) {
        return true;
    }
    if (num % 2 == 0 || num % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= num; i += 6) {
        if (num % i == 0 || num % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

