public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }

    StringBuilder escaped = new StringBuilder();
    boolean nextEscape = false;

    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        if (nextEscape) {
            switch(c) {
                case 'b':
                    escaped.append('\b');
                    break;
                case 't':
                    escaped.append('\t');
                    break;
                case 'n':
                    escaped.append('\n');
                    break;
                case 'f':
                    escaped.append('\f');
                    break;
                case 'r':
                    escaped.append('\r');
                    break;
                case '\"':
                    escaped.append('\"');
                    break;
                case '\'':
                    escaped.append('\'');
                    break;
                case '\\':
                    escaped.append('\\');
                    break;
                default:
                    escaped.append('\\').append(c);
                    break;
            }
            nextEscape = false;
        } else if (c == '\\') {
            nextEscape = true;
        } else {
            escaped.append(c);
        }
    }

    return escaped.toString();
}

