final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Check if the constantPoolEntryIndex is within the valid range
    if (constantPoolEntryIndex < 0) {
        throw new IllegalArgumentException("constantPoolEntryIndex must be non-negative");
    }

    // Assuming classFileBuffer is a byte array and is a member of a larger class
    // byte[] classFileBuffer;

    // Calculate the offset of the CONSTANT_Utf8 entry in the constant pool
    int offset = classFileBuffer[constantPoolEntryIndex + 1] << 8 | classFileBuffer[constantPoolEntryIndex + 2];

    // Check if the offset is within the bounds of the classFileBuffer
    if (offset < 0 || offset + 2 > classFileBuffer.length) {
        throw new ArrayIndexOutOfBoundsException("Offset out of bounds");
    }

    // Read the length of the UTF-8 encoded string
    int length = classFileBuffer[offset] & 0xFF;

    // Ensure the charBuffer is sufficiently large to hold the string
    if (charBuffer.length < length) {
        throw new IllegalArgumentException("charBuffer is too small");
    }

    // Read the UTF-8 encoded bytes
    int utf8Offset = offset + 1;
    for (int i = 0; i < length; i++) {
        charBuffer[i] = (char) (classFileBuffer[utf8Offset++] & 0xFF);
    }

    // Convert the char array to a String and return
    return new String(charBuffer, 0, length);
}

