public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Check for invalid input parameters
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength cannot be negative");
    }
    if (byteOffset < 0) {
        throw new IllegalArgumentException("byteOffset cannot be negative");
    }
    if (byteArrayValue != null && (byteOffset + byteLength) > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset + byteLength is out of the bounds of byteArrayValue");
    }

    // Calculate the new length of the byte vector
    int newLength = this.length + byteLength;
    if (newLength > this.capacity) {
        // Enlarge the byte vector if necessary
        this.capacity = calculateCapacity(newLength);
        this.array = Arrays.copyOf(this.array, this.capacity);
    }

    // Copy the bytes from the input array to the byte vector
    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, this.array, this.length, byteLength);
    } else {
        Arrays.fill(this.array, this.length, this.length + byteLength, (byte) 0);
    }

    // Update the length of the byte vector
    this.length = newLength;

    // Return this byte vector
    return this;
}

private int calculateCapacity(int minCapacity) {
    // Doubling the capacity to ensure efficient resizing
    int newCapacity = minCapacity;
    if (newCapacity < 16) {
        newCapacity = 16;
    }
    while (newCapacity < minCapacity) {
        newCapacity <<= 1;
    }
    return newCapacity;
}

