        throw new IllegalArgumentException("Graph is null");
    }

    // Initialize the path
    List<E> edges = new ArrayList<>(tour);
    V startVertex = null;
    V endVertex = null;

    // Find the start and end vertices
    for (E edge : edges) {
        startVertex = graph.getEdgeSource(edge);
        endVertex = graph.getEdgeTarget(edge);

        // Check if the graph contains the edge
        if (!graph.containsEdge(edge)) {
            throw new IllegalArgumentException("Graph does not contain the edge");
        }
    }

    // The tour is represented as a single path, so we can create a path with a single cycle
    List<E> pathEdges = new ArrayList<>();
    pathEdges.addAll(edges);
    pathEdges.add(edges.get(0)); // Close the cycle

    return new GraphPathImpl<>(graph, startVertex, endVertex, pathEdges);
}

