    if (node == null) {
        return false; // Node to unlink is null, do nothing and return false
    }

    ListNodeImpl<E> next = node.getNext();
    ListNodeImpl<E> prev = node.getPrevious();

    if (next != null) {
        next.setPrevious(prev);
    }

    if (prev != null) {
        prev.setNext(next);
    }

    node.setNext(null);
    node.setPrevious(null);

    return true; // Node successfully unlinked
}

