private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }

    long totalSum = bounds.stream().mapToLong(Long::longValue).sum();
    List<Integer> suffixSum = new ArrayList<>(Collections.nCopies(bounds.size(), 0));
    suffixSum.set(bounds.size() - 1, bounds.get(bounds.size() - 1));

    for (int i = bounds.size() - 2; i >= 0; i--) {
        suffixSum.set(i, suffixSum.get(i + 1) + bounds.get(i));
    }

    return new Pair<>(suffixSum, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (from < 0 || from > to) {
        throw new IllegalArgumentException("Invalid range");
    }
    if (to >= arr.length) {
        throw new IllegalArgumentException("End index out of bounds");
    }

    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

