private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<Integer,E> graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    for (Edge<E> edge : graph.edgeSet()) {
        int source = edge.getSource().getId();
        int target = edge.getTarget().getId();
        Set<Integer> neighborsSource = graph.neighborListOf(source);
        Set<Integer> neighborsTarget = graph.neighborListOf(target);

        Set<Integer> commonNeighbors = new HashSet<>(neighborsSource);
        commonNeighbors.retainAll(neighborsTarget);

        List<Pair<Integer,Integer>> minimalSeparators = new ArrayList<>();
        for (Integer neighbor : commonNeighbors) {
            if (neighbor != source && neighbor != target) {
                List<Integer> path = findPath(graph, source, target, neighbor);
                if (path != null) {
                    minimalSeparators.add(new Pair<>(path, edge.getWeight()));
                }
            }
        }

        globalSeparatorList.add(new Pair<>(minimalSeparators, edge));
    }

    return globalSeparatorList;
}

private List<Integer> findPath(Graph<Integer,E> graph, int source, int target, int neighbor) {
    List<Integer> path = new ArrayList<>();
    return findPathUtil(graph, source, target, neighbor, path);
}

private boolean findPathUtil(Graph<Integer,E> graph, int source, int target, int neighbor, List<Integer> path) {
    if (source == target) {
        path.add(source);
        return true;
    }

    graph.addVertex(neighbor);
    graph.addEdge(source, neighbor, neighbor);
    graph.addEdge(neighbor, target, neighbor);

    for (Integer nextNeighbor : graph.neighborListOf(neighbor)) {
        if (nextNeighbor != source && nextNeighbor != target) {
            path.add(neighbor);
            if (findPathUtil(graph, nextNeighbor, target, neighbor, path)) {
                return true;
            }
            path.remove(path.size() - 1);
        }
    }

    graph.removeVertex(neighbor);
    graph.removeEdge(source, neighbor);
    graph.removeEdge(neighbor, target);

    return false;
}

