private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true; // An empty graph is trivially a clique.
    }

    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 == v2) {
                continue; // No need to check edges to oneself.
            }
            if (!graph.containsEdge(v1, v2)) {
                return false; // Found an edge missing; not a clique.
            }
        }
    }
    return true; // All pairs of vertices have an edge between them.
}

