public static String applyRelativePath(String path, String relativePath) {
    if (path == null || path.isEmpty() || relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Path and relative path must not be null or empty");
    }

    // Split the paths into components
    String[] baseParts = path.split("/");
    String[] relativeParts = relativePath.split("/");

    // Remove trailing slash from base path if present
    if (baseParts[baseParts.length - 1].isEmpty()) {
        baseParts = Arrays.copyOf(baseParts, baseParts.length - 1);
    }

    // Process the relative path components
    for (String part : relativeParts) {
        if ("..".equals(part)) {
            if (baseParts.length > 0) {
                baseParts = Arrays.copyOf(baseParts, baseParts.length - 1);
            }
        } else if (!".".equals(part)) {
            baseParts = Arrays.copyOf(baseParts, baseParts.length);
            baseParts[baseParts.length - 1] = part;
        }
    }

    // Reconstruct the full path
    return String.join("/", baseParts);
}

