public int readTag() throws IOException {
    int b = in.read();
    if (b == -1) {
        return 0; // EOF
    }
    int fieldNumber = (b & 0x7F);
    int wireType = (b & 0x80) == 0 ? 0 : (b & 0x7F);
    if (wireType > 5) {
        throw new IOException("Invalid wire type: " + wireType);
    }
    while ((b = in.read()) != -1 && (b & 0x80) != 0) {
        fieldNumber = (fieldNumber << 7) | (b & 0x7F);
    }
    if (fieldNumber == 0) {
        throw new IOException("Invalid field number: 0");
    }
    return fieldNumber << 3 | wireType;
}

